// Shared classification data; eligibility decisions live only in the policy script.
export const CHARACTER_CONTENT_POLICY_SPEC=Object.freeze({version:'1.0.1',agePattern:'^(\\d{1,3})(?:\\s*岁)?$',maxAge:120,key:'__HYPNOOS_CHARACTER_CONTENT_POLICY__',readyEvent:'hypnoos:character-content-policy-ready',sexualFields:'敏感|乳房|子嗣|三围|性欲|快感|阴茎|龟头|前列腺|阴蒂|小穴|菊穴|尿道|乳头|高潮|妊娠|受孕|性交|性器|内裤|内衣',sexualText:'性器|阴茎|阴蒂|龟头|前列腺|小穴|菊穴|乳头|乳房|巨乳|肉壶|媚娃|走光|裸露|赤裸|裸体|性欲|内裤|内衣|情欲|淫|性交|高潮|色气|媚鬼|发情',sexualCommandIds:['vip1_temp_sensitivity','vip1_estrus','vip2_pleasure','vip2_ghost_hand','vip2_pain_to_pleasure','vip2_emperors_new_clothes','vip2_new_emperor','vip3_forced','vip3_orgasm_ban','vip3_shame_invert','vip3_pseudo_time_stop','vip5_excretion_control','vip5_lactation','vip5_fetish_implant','vip6_pregnancy_confirmation']});

export function parseCharacterSourceAge(raw,spec=CHARACTER_CONTENT_POLICY_SPEC){const match=String(raw??'').trim().match(new RegExp(spec.agePattern));if(!match)return null;const age=Number(match[1]);return Number.isInteger(age)&&age>0&&age<=spec.maxAge?age:null;}
